  8686	        unsigned const gnu_shift = get_te32(&gashtab[3]);
  8687	        unsigned const *const bitmask = &gashtab[4];
  8688	        unsigned const *const buckets = &bitmask[n_bitmask];
  8689	        unsigned const *const hasharr = &buckets[n_bucket];
